INSERT INTO changelog (title, body, created_at) VALUES ('Звіт для клієнта за посиланням і тижнева чернетка звіту', 'Клієнт → Meta → «Звіт для клієнта» → «Увімкнути посилання». Клієнт відкриває сторінку без входу і бачить: заявки та ціну заявки (тиждень проти тижня), графік за 14 днів, заявки з форм (скільки взяли в роботу, % якісних), креативи, що приводять заявки найдешевше, і «Що ми зробили за місяць» (журнал змін реклами + історія робіт). Наших витрат, маржі і нотаток там нема. «Нове посилання» — старе перестає працювати. «Вимкнути» — сторінка закривається.
Щопонеділка о 10:00 Джері пише чернетку тижневого звіту для кожного клієнта з рекламою (цифри, заявки, що змінили, план) і шле тобі в Telegram — перевіряєш і пересилаєш. Тумблер — «Можливості» → «Тижнева чернетка звіту клієнтам».', datetime('now'));
